                        </Badge>
                      </div>
                    </motion.div>
                  ))}
                </div>
                <Button variant="primary" size="sm" className="w-full mt-4 bg-gradient-to-r from-cyan-500 to-blue-500 shadow-lg shadow-cyan-500/20 hover:shadow-cyan-500/40 transition-all"
