                        <ChevronRight className="w-4 h-4 text-slate-600 group-hover:text-cyan-400 group-hover:translate-x-1 transition-all" />
                      </motion.div>
                    );
                  })}
                </div>
              </GlassmorphicCard>
            </div>
          </div>

          {/* 🆕 HEALTH DISTRIBUTION PIE CHART */}
