      } else {
        setError('Invalid email or password for the selected role');
        toast.error('Login failed. Please check your credentials.');
      }
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : 'Login failed. Please try again.';
      setError(message);
      toast.error(message);
    } finally {
      setIsLoading(false);
    }
  };

