                    id="rememberMe"
                    checked={formData.rememberMe}
                    onChange={(e) => setFormData(prev => ({ ...prev, rememberMe: e.target.checked }))}
                    className="w-4 h-4 rounded border-white/[0.1] bg-white/[0.02] text-cyan-500 focus:ring-cyan-500 focus:ring-offset-0"
                  />
                  <label htmlFor="rememberMe" className="text-white/40 text-xs cursor-pointer">
                    Remember me for 30 days
                  </label>
                </div>

                <motion.button
                  type="submit"
                  disabled={isLoading}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  className={`w-full py-4 rounded-2xl font-semibold text-base transition-all flex items-center justify-center gap-2 ${
                    isLoading
                      ? 'bg-white/[0.05] text-white/30 cursor-not-allowed'
                      : `bg-gradient-to-r ${roleConfig[selectedRole].gradient} text-white shadow-lg`
                  }`}
                >
                  {isLoading ? (
                    <><svg className="animate-spin w-5 h-5" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"/><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"/></svg> Signing in...</>
                  ) : (
                    <>Sign In as {roleConfig[selectedRole].label} <ArrowRight className="w-5 h-5" /></>
                  )}
                </motion.button>
              </form>
            ) : (
              // Registration Form
              <form onSubmit={handleRegister} className="space-y-4">
                <div>
                  <label className="text-white/40 text-xs font-medium uppercase tracking-wider mb-2 block">
                    Full Name
                  </label>
                  <div className="relative">
                    <UserCog className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-white/20" />
                    <input
                      type="text"
                      value={registerData.fullName}
                      onChange={(e) => setRegisterData(prev => ({ ...prev, fullName: e.target.value }))}
                      placeholder="Enter your full name"
                      className="w-full pl-12 pr-4 py-4 bg-white/[0.03] border border-white/[0.06] rounded-2xl text-white text-sm placeholder-white/20 outline-none focus:border-cyan-400/50 transition-all"
                    />
                  </div>
                  {fieldErrors.fullName && <p className="text-red-400 text-[11px] mt-1.5">{fieldErrors.fullName}</p>}
                </div>

                <div>
                  <label className="text-white/40 text-xs font-medium uppercase tracking-wider mb-2 block">
                    Email Address
                  </label>
                  <div className="relative">
                    <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-white/20" />
                    <input
                      type="email"
                      value={registerData.email}
                      onChange={(e) => setRegisterData(prev => ({ ...prev, email: e.target.value }))}
                      placeholder="Enter your email"
                      className="w-full pl-12 pr-4 py-4 bg-white/[0.03] border border-white/[0.06] rounded-2xl text-white text-sm placeholder-white/20 outline-none focus:border-cyan-400/50 transition-all"
                    />
                  </div>
                  {fieldErrors.email && <p className="text-red-400 text-[11px] mt-1.5">{fieldErrors.email}</p>}
                </div>

                <div>
                  <label className="text-white/40 text-xs font-medium uppercase tracking-wider mb-2 block">
                    Phone Number
                  </label>
                  <div className="relative">
                    <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-white/20" />
                    <input
                      type="tel"
                      value={registerData.phone}
                      onChange={(e) => setRegisterData(prev => ({ ...prev, phone: e.target.value }))}
                      placeholder="+1 (555) 000-0000"
                      className="w-full pl-12 pr-4 py-4 bg-white/[0.03] border border-white/[0.06] rounded-2xl text-white text-sm placeholder-white/20 outline-none focus:border-cyan-400/50 transition-all"
                    />
                  </div>
                  {fieldErrors.phone && <p className="text-red-400 text-[11px] mt-1.5">{fieldErrors.phone}</p>}
                </div>

                <div>
                  <label className="text-white/40 text-xs font-medium uppercase tracking-wider mb-2 block">
                    Password
                  </label>
                  <div className="relative">
                    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-white/20" />
                    <input
                      type="password"
                      value={registerData.password}
                      onChange={(e) => setRegisterData(prev => ({ ...prev, password: e.target.value }))}
                      placeholder="Create a password"
                      className="w-full pl-12 pr-4 py-4 bg-white/[0.03] border border-white/[0.06] rounded-2xl text-white text-sm placeholder-white/20 outline-none focus:border-cyan-400/50 transition-all"
                    />
                  </div>
                  {fieldErrors.password && <p className="text-red-400 text-[11px] mt-1.5">{fieldErrors.password}</p>}
                </div>

                <div>
                  <label className="text-white/40 text-xs font-medium uppercase tracking-wider mb-2 block">
                    Confirm Password
                  </label>
                  <div className="relative">
                    <CheckCircle className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-white/20" />
                    <input
                      type="password"
                      value={registerData.confirmPassword}
                      onChange={(e) => setRegisterData(prev => ({ ...prev, confirmPassword: e.target.value }))}
                      placeholder="Confirm your password"
                      className="w-full pl-12 pr-4 py-4 bg-white/[0.03] border border-white/[0.06] rounded-2xl text-white text-sm placeholder-white/20 outline-none focus:border-cyan-400/50 transition-all"
                    />
                  </div>
                  {fieldErrors.confirmPassword && <p className="text-red-400 text-[11px] mt-1.5">{fieldErrors.confirmPassword}</p>}
                </div>

                <div className="flex items-center gap-3">
                  <input
                    type="checkbox"
                    id="agreeTerms"
                    checked={registerData.agreeToTerms}
                    onChange={(e) => setRegisterData(prev => ({ ...prev, agreeToTerms: e.target.checked }))}
                    className="w-4 h-4 rounded border-white/[0.1] bg-white/[0.02] text-cyan-500 focus:ring-cyan-500"
                  />
                  <label htmlFor="agreeTerms" className="text-white/40 text-xs cursor-pointer">
                    I agree to the{' '}
                    <Link to="/terms" className="text-cyan-400 hover:text-cyan-300">Terms of Service</Link>
                    {' '}and{' '}
                    <Link to="/privacy" className="text-cyan-400 hover:text-cyan-300">Privacy Policy</Link>
                  </label>
                </div>
                {fieldErrors.agreeToTerms && <p className="text-red-400 text-[11px]">{fieldErrors.agreeToTerms}</p>}

                <motion.button
                  type="submit"
                  disabled={isLoading}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  className={`w-full py-4 rounded-2xl font-semibold text-base transition-all flex items-center justify-center gap-2 ${
                    isLoading
                      ? 'bg-white/[0.05] text-white/30 cursor-not-allowed'
                      : `bg-gradient-to-r ${roleConfig[registerData.role].gradient} text-white shadow-lg`
                  }`}
                >
                  {isLoading ? (
                    <><svg className="animate-spin w-5 h-5" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"/><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"/></svg> Creating Account...</>
                  ) : (
                    <>Create Account <UserPlus className="w-5 h-5" /></>
                  )}
                </motion.button>
              </form>
            )}

            <div className="text-center mt-6 pt-4 border-t border-white/[0.04]">
              <p className="text-white/30 text-sm">
                {isRegistering ? 'Already have an account?' : "Don't have an account?"}{' '}
                <button
                  type="button"
                  onClick={() => {
                    setIsRegistering(!isRegistering);
                    setError('');
                    setFieldErrors({});
                  }}
                  className="text-cyan-400 hover:text-cyan-300 font-semibold transition-colors inline-flex items-center gap-1 group"
                >
                  {isRegistering ? 'Sign In' : 'Create Account'}
                  <ChevronRight className="w-3.5 h-3.5 group-hover:translate-x-1 transition-transform" />
                </button>
              </p>
            </div>
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.8 }}
          className="text-center mt-6"
        >
          <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-white/[0.02] border border-white/[0.04] backdrop-blur-sm">
            <Shield className="w-3.5 h-3.5 text-emerald-400/60" />
            <span className="text-white/15 text-[11px] font-medium tracking-wider">
              • 256-bit Encrypted • Secure Login
            </span>
          </div>
        </motion.div>
      </div>
    </div>
  );
};

export default Login;

// src/components/layout/Navbar.tsx

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Link, useNavigate, useLocation, NavLink } from 'react-router-dom';
import { useAppSelector, useAppDispatch, RootState } from 'src/store';


import {
  Menu, X, ChevronDown, Bell, LogOut, User, Settings,
  LayoutDashboard, Activity, Building2, Pill, Search, Calendar, FileText, MessageCircle, Globe, Sun, Moon, CreditCardIcon, BellOff, AlertCircle,
  HelpCircle,
  Lock,
  Stethoscope,
  Bot,
  Heart,
  Droplet
} from 'lucide-react';

import { Button } from '../ui/Button';
import { Avatar } from '../ui/Avatar';
import { logout } from '../../store/slices/authSlice';
import { searchService, SearchResult } from '../../services/searchService';









interface NavbarProps {
  transparent?: boolean;
  variant?: 'default' | 'glass' | 'solid' | 'gradient';
  showSearch?: boolean;
  showNotifications?: boolean;
  showLanguageSelector?: boolean;
  showThemeToggle?: boolean;
  position?: 'fixed' | 'sticky' | 'relative';
}

interface Notification {
  id: string;
  title: string;
  message: string;
  type: 'info' | 'success' | 'warning' | 'error' | 'emergency';
  timestamp: Date;
  read: boolean;
  link?: string;
  icon?: React.ReactNode;
}

type SearchCategory = 'all' | 'doctor' | 'hospital' | 'medicine';








export const Navbar: React.FC<NavbarProps> = ({ 
  transparent = false, 
  variant = 'default',
  showSearch = true,
  showNotifications = true,
  showThemeToggle = true,
  position = 'fixed'
}) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [profileDropdownOpen, setProfileDropdownOpen] = useState(false);
  const [notificationOpen, setNotificationOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [searchCategory, setSearchCategory] = useState<SearchCategory>('all');
  const [userLocation, setUserLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('theme');
    return (saved as 'light' | 'dark') || 'dark';
  });
  const [language, setLanguage] = useState('en');
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);

  const navigate = useNavigate();
  const location = useLocation();
  const dispatch = useAppDispatch();
  const searchRef = useRef<HTMLDivElement>(null);
  const notificationRef = useRef<HTMLDivElement>(null);
  const profileRef = useRef<HTMLDivElement>(null);

  // Safe Redux access
  const authState = useAppSelector((state: RootState) => state.auth);
  const user = authState?.user || null;
  const isAuthenticated = authState?.isAuthenticated || false;

  // Theme management
  useEffect(() => {
    document.documentElement.classList.toggle('dark', theme === 'dark');
    localStorage.setItem('theme', theme);
  }, [theme]);










  // Scroll handler
  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // User location
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((position) => {
        setUserLocation({
          lat: position.coords.latitude,
          lng: position.coords.longitude,
        });
      });
    }
  }, []);

  // Click outside handlers
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setSearchOpen(false);
        setSearchQuery('');
      }
      if (notificationRef.current && !notificationRef.current.contains(event.target as Node)) {
        setNotificationOpen(false);
      }
      if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
        setProfileDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Fetch notifications
  useEffect(() => {
    if (isAuthenticated) {
      fetchNotifications();
    }
  }, [isAuthenticated]);

  const fetchNotifications = async () => {
    // Mock notifications - replace with API call
    const mockNotifications: Notification[] = [
      {
        id: '1',
        title: 'Emergency Alert',
        message: 'Code Blue - ICU Room 302',
        type: 'emergency',
        timestamp: new Date(),
        read: false,
        icon: <AlertCircle className="w-4 h-4" />
      },
      {
        id: '2',
        title: 'Appointment Reminder',
        message: 'You have a doctor appointment tomorrow at 10:00 AM',
        type: 'info',
        timestamp: new Date(Date.now() - 3600000),
        read: false,
        icon: <Calendar className="w-4 h-4" />
      },
      

    ];
    setNotifications(mockNotifications);
    setUnreadCount(mockNotifications.filter(n => !n.read).length);
  };

  // Search functionality
  const handleSearch = useCallback(async (query: string) => {
    setSearchQuery(query);
    if (!query.trim()) {
      setSearchResults([]);
      return;
    }

    setIsSearching(true);
    try {
      let results: SearchResult[];

      switch (searchCategory) {
        case 'doctor':
          results = await searchService.searchDoctors(query, userLocation || undefined);
          break;
        case 'hospital':
          results = await searchService.searchHospitals(query, userLocation || undefined);
          break;
        case 'medicine':
          results = await searchService.searchMedicines(query);
          break;
        default:
          results = await searchService.globalSearch(query, userLocation || undefined);
      }

      setSearchResults(results);
    } catch (error) {
      console.error('Search error:', error);
    } finally {
      setIsSearching(false);
    }
  }, [searchCategory, userLocation]);

  const navLinks = [
    { label: 'Doctors', path: '/doctor', icon: Stethoscope },
    { label: 'Hospital', path: '/hospital', icon: Building2 },
    { label: 'Medicine', path: '/pharmacy', icon: Pill },
    { label: 'Women Care', path: '/women-care', icon: Heart },
    { label: 'Blood Donor', path: '/blood-donors', icon: Droplet },
    { label: 'AI Assistant', path: '/ai-assistant', icon: Bot },
  ];

  const getAuthenticatedLinks = () => {
    const primaryRole = user?.role || user?.primaryRole || 'patient';
    
    const roleLinks: Record<string, { label: string; path: string; icon: React.ElementType }[]> = {
      patient: [
        { label: 'Dashboard', path: '/patient/dashboard', icon: LayoutDashboard },
        { label: 'Appointments', path: '/patient/appointments', icon: Calendar },
        { label: 'Messages', path: '/patient/messages', icon: MessageCircle },
        { label: 'Health Records', path: '/patient/records', icon: FileText },
        { label: 'Billing', path: '/patient/billing', icon: CreditCardIcon }
      ],
      doctor: [
        { label: 'Dashboard', path: '/doctor/dashboard', icon: LayoutDashboard },
        { label: 'Appointments', path: '/doctor/appointments', icon: Calendar },
        { label: 'Patients', path: '/doctor/patients', icon: User },
        { label: 'Schedule', path: '/doctor/schedule', icon: Calendar },
        { label: 'Messages', path: '/doctor/messages', icon: MessageCircle },
      ],
      hospital: [
        { label: 'Dashboard', path: '/hospital/dashboard', icon: LayoutDashboard },
        { label: 'Account', path: '/hospital/account', icon: Settings },
        { label: 'Admin', path: '/hospital/admin', icon: Building2 },
      ],
      pharmacy: [
        { label: 'Dashboard', path: '/pharmacy/dashboard', icon: LayoutDashboard },
        { label: 'Account', path: '/pharmacy/account', icon: Settings },
        { label: 'Stock', path: '/pharmacy/stock', icon: FileText },
      ],
      admin: [
        { label: 'Dashboard', path: '/admin/dashboard', icon: LayoutDashboard },
        { label: 'Users', path: '/admin/users', icon: User },
        { label: 'Doctors', path: '/admin/doctor-verification', icon: Stethoscope },
        { label: 'Hospitals', path: '/admin/hospitals', icon: Building2 },
        { label: 'Analytics', path: '/admin/analytics', icon: FileText },
      ],
    };

    return roleLinks[primaryRole] || roleLinks['patient'];
  };

  const handleNavigate = (path: string) => {
    setMobileMenuOpen(false);
    setProfileDropdownOpen(false);
    setNotificationOpen(false);
    setSearchOpen(false);
    navigate(path);
  };

  const handleLogout = async () => {
    try {
      await dispatch(logout());
      handleNavigate('/');
    } catch (error) {
      console.error('Logout error:', error);
    }
  };

  const markNotificationAsRead = (id: string) => {
    setNotifications(prev =>
      prev.map(notif =>
        notif.id === id ? { ...notif, read: true } : notif
      )
    );
    setUnreadCount(prev => Math.max(0, prev - 1));
  };

  const markAllAsRead = () => {
    setNotifications(prev =>
      prev.map(notif => ({ ...notif, read: true }))
    );
    setUnreadCount(0);
  };

  const getVariantClasses = () => {
    if (variant === 'glass') {
      return 'bg-white/10 dark:bg-slate-900/20 backdrop-blur-xl border border-white/20';
    }
    if (variant === 'solid') {
      return 'bg-white dark:bg-slate-900 shadow-lg';
    }
    if (variant === 'gradient') {
      return 'bg-gradient-to-r from-blue-600 to-teal-600';
    }
    if (transparent && !isScrolled) {
      return 'bg-transparent';
    }
    return 'bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-gray-200 dark:border-white/10';
  };

  const getThemeIcon = () => {
    if (theme === 'dark') return <Sun className="w-4 h-4" />;
    return <Moon className="w-4 h-4" />;
  };

  return (
    <>
      <motion.nav
        initial={{ y: -100 }}
        animate={{ y: 0 }}
        transition={{ duration: 0.6, ease: 'easeOut' }}
        className={`
          ${position}
          top-0 left-0 right-0 z-[999]
          transition-all duration-500
          ${getVariantClasses()}
        `}
      >
        <div className="w-full px-0">
          <div className="flex items-center justify-between h-16 lg:h-20 2xl:h-24 pl-1 sm:pl-2 lg:pl-4 pr-4 sm:pr-6 lg:pr-8 2xl:pr-12">

            {/* LOGO */}
            <Link to="/" className="flex items-center gap-2 group" aria-label="Home">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-blue-500 to-teal-500 flex items-center justify-center shadow-lg shadow-blue-500/20 group-hover:scale-105 transition-transform">
                <Activity className="w-6 h-6 text-white" />
              </div>
              <span className="hidden sm:inline text-2xl lg:text-3xl 2xl:text-4xl font-bold bg-gradient-to-r from-blue-500 to-teal-500 bg-clip-text text-transparent">
                HealthCare+
              </span>
            </Link>

            {/* DESKTOP MENU */}
            <div className="hidden md:flex items-center gap-4 lg:gap-6 2xl:gap-8">
              {navLinks.map((item) => {
                const Icon = item.icon;

                return (
                  <NavLink
                    key={item.path}
                    to={item.path}
                    className={({ isActive }) => `
                      relative flex items-center gap-1.5 px-1.5 lg:px-2 py-1.5 rounded-lg text-[9px] lg:text-[11px] font-medium transition-all
                      ${isActive
                        ? 'text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-500/10'
                        : 'text-gray-700 dark:text-slate-300 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-500/5'
                      }
                    `}
                  >
                    <Icon className="w-4 h-4" />
                    {item.label}
                  </NavLink>
                );
              }              )}
            </div>

            {/* RIGHT SIDE */}
            <div className="flex items-center gap-4 sm:gap-5 lg:gap-6 2xl:gap-8">

              {/* SEARCH */}
              {showSearch && (
                <div className="relative" ref={searchRef}>
                  <button 
                    onClick={() => setSearchOpen(!searchOpen)}
                    className="p-2 rounded-xl hover:bg-gray-100 dark:hover:bg-white/5 transition-all"
                    aria-label="Search"
                  >
                    <Search className="w-5 h-5 text-gray-600 dark:text-slate-300" />
                  </button>









                  <AnimatePresence>
                    {searchOpen && (
                      <motion.div
                        initial={{ opacity: 0, y: 10, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 10, scale: 0.95 }}
                        className="absolute right-0 top-12 w-96 bg-white dark:bg-slate-900 rounded-2xl shadow-2xl border border-gray-200 dark:border-white/10 p-4 z-50"
                      >
                        <div className="relative">
                          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                          <input
                            type="text"
                            placeholder="Search doctors, hospitals, medicines..."
                            value={searchQuery}
                            onChange={(e) => handleSearch(e.target.value)}
                            className="w-full pl-10 pr-4 py-2 rounded-xl bg-gray-100 dark:bg-white/5 border-0 focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-white placeholder-gray-500"
                            autoFocus
                          />
                          {searchQuery && (
                            <button
                              onClick={() => { setSearchQuery(''); setSearchResults([]); }}
                              className="absolute right-3 top-1/2 -translate-y-1/2"
                            >
                              <X className="w-4 h-4 text-gray-400 hover:text-gray-600" />
                            </button>
                          )}
                        </div>

                        {/* Category Tabs */}
                        <div className="flex gap-1 mt-3">
                          {([
                            { key: 'all', label: 'All', icon: Search },
                            { key: 'doctor', label: 'Doctors', icon: Stethoscope },
                            { key: 'hospital', label: 'Hospitals', icon: Building2 },
                            { key: 'medicine', label: 'Medicine', icon: Pill },
                          ] as const).map(({ key, label, icon: TabIcon }) => (
                            <button
                              key={key}
                              onClick={() => { setSearchCategory(key); if (searchQuery) handleSearch(searchQuery); }}
                              className={`flex items-center gap-1 px-2.5 py-1.5 rounded-lg text-xs font-medium transition-all ${
                                searchCategory === key
                                  ? 'bg-blue-100 dark:bg-blue-500/20 text-blue-600 dark:text-blue-400'
                                  : 'text-gray-500 dark:text-slate-400 hover:bg-gray-100 dark:hover:bg-white/5'
                              }`}
                            >
                              <TabIcon className="w-3 h-3" />
                              {label}
                            </button>
                          ))}
                        </div>

                        {isSearching ? (
                          <div className="flex items-center justify-center py-8">
                            <div className="animate-spin rounded-full h-8 w-8 border-2 border-blue-500 border-t-transparent" />
                          </div>
                        ) : searchResults.length > 0 ? (
                          <div className="mt-3 space-y-2 max-h-96 overflow-y-auto">
                            {searchResults.map((result) => {
                              const typeIcon = result.type === 'doctor' ? <Stethoscope className="w-4 h-4" />
                                : result.type === 'hospital' ? <Building2 className="w-4 h-4" />
                                : <Pill className="w-4 h-4" />;
